import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { logoutUser, getAuthToken, getUserInfo } from '../api';
import './Navbar.css';
import logoPath from '../assets/collabify-logo.png';

const Navbar = ({ isAuthenticated }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [user, setUser] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchUserData = async () => {
      try {
        if (isAuthenticated) {
          // We need to implement a proper way to get the current user ID
          // For now, we'll use a placeholder or localStorage
          const userId = localStorage.getItem('userId');

          if (userId) {
            const userData = await getUserInfo(userId);
            setUser(userData);
          }
        } else {
          setUser(null);
        }
      } catch (error) {
        console.error("Error fetching user data:", error);
      }
    };

    fetchUserData();
  }, [isAuthenticated]);

  const toggleMenu = () => {
    setIsOpen(!isOpen);
  };

  const handleLogout = async () => {
    try {
      await logoutUser();
      window.dispatchEvent(new Event('auth-change'));
      navigate('/');
    } catch (error) {
      console.error("Logout error:", error);
    }
  };

  const getInitials = () => {
    if (user && user.username) {
      return user.username.charAt(0).toUpperCase();
    }
    return "?";
  };

  return (
    <nav className="navbar">
      <div className="navbar-container">
        <Link to="/" className="navbar-logo">
          <img src={logoPath} alt="Collabify" className="logo-image" />
          <span className="logo-text">collabify</span>
        </Link>

        <div className="menu-icon" onClick={toggleMenu}>
          <div className={`hamburger ${isOpen ? 'open' : ''}`}>
            <span></span>
            <span></span>
            <span></span>
          </div>
        </div>

        <ul className={`nav-menu ${isOpen ? 'active' : ''}`}>
          <li className="nav-item">
            <Link to="/" className="nav-link" onClick={() => setIsOpen(false)}>
              Home
            </Link>
          </li>

          {isAuthenticated ? (
            // Authenticated menu items
            <>
              <li className="nav-item">
                <Link to="/profiles" className="nav-link" onClick={() => setIsOpen(false)}>
                  Discover
                </Link>
              </li>
              <li className="nav-item">
                <Link to="/friends" className="nav-link" onClick={() => setIsOpen(false)}>
                  Friends
                </Link>
              </li>
              <li className="nav-item">
                <Link to="/messages" className="nav-link" onClick={() => setIsOpen(false)}>
                  Messages
                </Link>
              </li>
              <li className="nav-item">
                <Link to="/upload" className="nav-link" onClick={() => setIsOpen(false)}>
                  Upload
                </Link>
              </li>
              <li className="nav-item profile-item">
                <Link to="/profile" className="nav-link profile-link" onClick={() => setIsOpen(false)}>
                  <div className="profile-circle">
                    <span>{getInitials()}</span>
                  </div>
                </Link>
              </li>
              <li className="nav-item">
                <button className="nav-link logout-button" onClick={handleLogout}>
                  Logout
                </button>
              </li>
            </>
          ) : (
            // Non-authenticated menu items
            <>
              <li className="nav-item">
                <Link to="/login" className="nav-link" onClick={() => setIsOpen(false)}>
                  Login
                </Link>
              </li>
              <li className="nav-item">
                <Link to="/register" className="nav-link register-link" onClick={() => setIsOpen(false)}>
                  Register
                </Link>
              </li>
            </>
          )}
        </ul>
      </div>
    </nav>
  );
};

export default Navbar;
